                            x: [null],
                            y: [null],
                            mode: 'markers',
                            type: 'scatter',
                            name: entry.label,
                            legendgroup: groupKey,
                            showlegend: true,
                            marker: {
                                size: 8,
                                color: entry.color,
                                symbol: 'circle',
                            },
                            hoverinfo: 'skip',
